import json

n = 33146799

def factorize(num):
    factors = {}
    m = num
    d = 2
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def is_prime(k):
    if k < 2:
        return False
    d = 2
    while d * d <= k:
        if k % d == 0:
            return False
        d += 1
    return True

factors = factorize(n)

product = 1
for p, e in factors.items():
    product *= p ** e

all_prime = all(is_prime(p) for p in factors)

if product != n or not all_prime or not factors:
    print("UNSUPPORTED")
else:
    prime_list = []
    for p in sorted(factors):
        prime_list.extend([p] * factors[p])

    result = {
        "final_answer": " * ".join(str(p) for p in prime_list),
        "evidence": {
            "n": n,
            "distinct_primes": sorted(factors.keys()),
            "multiplicities": {str(p): factors[p] for p in sorted(factors)},
            "product_check": product == n,
            "all_factors_prime": all_prime,
            "method": "trial_division_up_to_sqrt"
        }
    }
    print(json.dumps(result, separators=(",", ":")))
